mapper.select:
select syo.*
from sal_yt_order as syo where is_deleted = 0
and id = #{id}

select DATE_FORMAT(syo.create_time, '%Y-%m') as month, COALESCE( sum( (select sum(syosi.price * syosi.number) from sal_yt_order_sub_item syosi where syosi.order_sub_id = syos.id and syosi.is_deleted = 0) + (case when syos.is_collected_shipping_cost = 1 then COALESCE(syos.shipping_cost, 0) else 0 end) ), 0 ) as amount from sal_yt_order as syo left join sal_yt_order_sub syos on syos.order_id = syo.id and syos.is_deleted = 0 where syo.is_deleted = 0 and syo.customer_id = #{customerId} and syo.status>=5
and syo.create_time >= #{startTime}
and syo.create_time <= #{endTime}
group by DATE_FORMAT(syo.create_time, '%Y-%m') order by month

select pc.name as categoryName, COALESCE( sum( syosi.price * syosi.number ), 0 ) as amount from sal_yt_order as syo left join sal_yt_order_sub syos on syos.order_id = syo.id and syos.is_deleted = 0 left join sal_yt_order_sub_item syosi on syosi.order_sub_id = syos.id and syosi.is_deleted = 0 left join pro_yt_product p on p.id = syosi.product_id and p.is_deleted = 0 left join pro_yt_product_category pc on pc.id = p.category_id and pc.is_deleted = 0 where syo.is_deleted = 0 and syo.customer_id = #{customerId} and syo.status>=5
and syo.create_time >= #{startTime}
and syo.create_time <= #{endTime}
and pc.name is not null group by pc.id, pc.name order by amount desc

